def materialize(directory: Path) -> Path:
    directory.mkdir(parents=True, exist_ok=True)
    target = directory / "index.html"
    if target.is_file() and hashlib.sha256(target.read_bytes()).hexdigest() == DOCUMENT_SHA256:
        return target
    data = gzip.decompress(base64.b64decode(DOCUMENT, validate=True))
    if hashlib.sha256(data).hexdigest() != DOCUMENT_SHA256:
        raise ValueError("Embedded application failed the integrity check.")
    with tempfile.NamedTemporaryFile(dir=directory, delete=False) as output:
        temporary = Path(output.name)
        try:
            output.write(data)
        except BaseException:
            output.close()
            temporary.unlink(missing_ok=True)
            raise
    try:
        os.replace(temporary, target)
    finally:
        temporary.unlink(missing_ok=True)
    return target


def main() -> int:
    from PyQt6.QtCore import QStandardPaths, QTimer, QUrl
    from PyQt6.QtWidgets import QApplication, QFileDialog, QMainWindow, QMessageBox
    from PyQt6.QtWebEngineWidgets import QWebEngineView

    smoke = "--smoke-test" in sys.argv[1:]
    app = QApplication([sys.argv[0]])
    app.setOrganizationName("Marja")
    app.setApplicationName("MarjaCAN")
    root = Path(QStandardPaths.writableLocation(QStandardPaths.StandardLocation.AppLocalDataLocation))
    window = QMainWindow()
    window.setWindowTitle("بررسی لاگ شبکه CAN · واحد مهندسی محصول")
    try:
        page_path = materialize(root / "app")
    except (OSError, ValueError) as error:
        if not smoke:
            QMessageBox.critical(window, "بررسی لاگ شبکه CAN", str(error))
        return 1
    view = QWebEngineView(window)
    window.setCentralWidget(view)
    window.resize(1250, 820)

    def save_download(item):
        path, _ = QFileDialog.getSaveFileName(window, "ذخیرهٔ فایل", item.downloadFileName())
        if path:
            destination = Path(path)
            item.setDownloadDirectory(str(destination.parent))
            item.setDownloadFileName(destination.name)
            item.accept()
        else:
            item.cancel()

    def loaded(ok):
        if smoke:
            if not ok:
                app.exit(2)
                return
            check_ready()

        elif not ok:
            QMessageBox.critical(window, "بررسی لاگ شبکه CAN", "بارگذاری برنامه انجام نشد.")

    def check_ready():
        view.page().runJavaScript(
            "['logs','walkNext','leftRun','rightRun','framesAdd'].every(id => "
            "document.getElementById(id)) && typeof document.getElementById('logs').onchange === 'function'",
            0,
            lambda ready: app.exit(0) if ready is True else QTimer.singleShot(100, check_ready),
        )

    view.page().profile().downloadRequested.connect(save_download)
    view.loadFinished.connect(loaded)
    if smoke:
        QTimer.singleShot(45000, lambda: app.exit(4))
    else:
        window.show()
    view.load(QUrl.fromLocalFile(str(page_path)))
    return app.exec()


if __name__ == "__main__":
    sys.exit(main())
